export default async function next(
  { body, article, email, acknowledge, resolution, confirmedLink },
  ctx,
) {
  const id = body?.pageId;
  if (!id || !body?.name || !email || email.includes("YOUR_"))
    throw Error("Configure page and email");
  const key = "notion-blog:" + id;
  let s = await ctx.state.get(key);
  if (!s) {
    if (body.status === "publish")
      return { action: "done", key, title: "", content: "", link: "", email, properties: {} };
    if (!article?.title || !article?.content) throw Error("Invalid article");
    s = { article, phase: "post", pending: null, link: "" };
    await ctx.state.set(key, s);
  }
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + s.pending);
    if (resolution === "confirmed") {
      if (s.phase === "post") {
        if (!/^https?:\/\//.test(confirmedLink)) throw Error("Enter the confirmed draft URL");
        s.link = confirmedLink;
      }
      s.phase = { post: "email", email: "notion", notion: "done" }[s.phase];
    }
    s.pending = null;
    await ctx.state.set(key, s);
  }
  const action = s.phase,
    parts = s.article.content.match(/[\s\S]{1,1900}/g) || [],
    properties = {
      Subject: { rich_text: [{ text: { content: s.article.title } }] },
      Content: { rich_text: parts.map((content) => ({ text: { content } })) },
      URL: { url: s.link || null },
      Status: { select: { name: "publish" } },
    };
  if (action !== "done") {
    s.pending = key + ":" + action;
    await ctx.state.set(key, s);
  }
  return {
    action,
    key,
    title: s.article.title,
    content: s.article.content,
    link: s.link,
    email,
    properties,
  };
}

