async function confirm({ key, kind, post, messageId, page }, ctx) {
  const s = await ctx.state.get(key);
  if (!s?.pending || s.phase !== kind) throw Error("Missing pending operation");
  if (kind === "post") {
    if (!post?.id || post.status !== "draft" || !/^https?:\/\//.test(post.link ?? ""))
      throw Error("Unknown WordPress draft result");
    s.link = post.link;
  }
  if (kind === "email" && !messageId) throw Error("Unknown Gmail result");
  if (kind === "notion" && page?.id !== key.slice("notion-blog:".length))
    throw Error("Unknown Notion update");
  s.pending = null;
  s.phase = { post: "email", email: "notion", notion: "done" }[kind];
  await ctx.state.set(key, s);
  return { ok: true };
}

export default async function f(input, ctx) {
  return confirm({ ...input, kind: "post" }, ctx);
}

